mapper.sql:
select f.*
from ai_knowledge_folder f


        f.org_id = #{orgId}


        and f.data_status = #{dataStatus}

paths as ( select * from visible union select p.* from ai_knowledge_folder p join paths child on p.id = child.parent_id and p.org_id = child.org_id
where p.org_id = #{orgId}
) select * from paths order by sort_order, id

mapper.select:
select count(*)
from ai_knowledge_folder
where parent_id = #{folderId}
